/**
 * Shape of json/evolve-costs.json, generated by tools-js/build-evolve-costs.cjs
 * from the game's master data (evolve_equip).
 */
declare interface EvolveMaterial {
  mst_material_id: number;
  amount: number;
}

declare interface EvolveFodder {
  mst_equipment_id: number;
  /** Minimum plus value (potential) the sacrificed piece must have. */
  minPotential: number;
}

declare interface EvolveRow {
  /** Master name of the piece that evolves, in Japanese. */
  name: string;
  /** mst_equipment_id it becomes. */
  after: number;
  afterName: string;
  zeny: number;
  /** Equipment level the result starts at. */
  afterLevel: number;
  materials: EvolveMaterial[];
  equipments: EvolveFodder[];
}

declare interface EvolveCosts {
  _comment: string;
  _note: string;
  /** mst_equipment_id -> evolution data. */
  byEquipment: Record<string, EvolveRow>;
}

declare const EVOLVE: EvolveCosts;
export default EVOLVE;
